def snapshot_array(length, ops):
    import bisect
    hist = [[(0, 0)] for _ in range(length)]
    snap_id = 0
    out = []
    for op in ops:
        if op[0] == 'set':
            h = hist[op[1]]
            if h[-1][0] == snap_id:
                h[-1] = (snap_id, op[2])
            else:
                h.append((snap_id, op[2]))
        elif op[0] == 'snap':
            out.append(snap_id)
            snap_id += 1
        else:
            h = hist[op[1]]
            i = bisect.bisect_right(h, (op[2], float('inf'))) - 1
            out.append(h[i][1])
    return out
